if(EditorApplication.isPlaying)throw new System.Exception("Edit only");string D="ArtSource/Pipeline/Review/BriarwickFamilyCottageB01";var root=GameObject.Find("BW_FamilyCottageB01");var scene=root.scene;Physics.SyncTransforms();
