var mats=root.GetComponentsInChildren<Renderer>().SelectMany(r=>r.sharedMaterials).Distinct().Select(m=>new{name=m.name,supported=m.shader.isSupported,missingTextures=m.GetTexturePropertyNames().Count(n=>m.GetTexture(n)!=null&&!System.IO.File.Exists(AssetDatabase.GetAssetPath(m.GetTexture(n))))}).ToArray();
