float Hit(Vector3 p,Vector3 d){return cols.Select(c=>{RaycastHit h;return c.Raycast(new Ray(root.transform.TransformPoint(p),root.transform.TransformDirection(d)),out h,4)?h.distance:100f;}).Min();}
var main=new{role="Main doorway",width=Hit(new Vector3(0,1.3f,4),Vector3.left)+Hit(new Vector3(0,1.3f,4),Vector3.right),height=Hit(new Vector3(0,.32f,4),Vector3.up)+.2f};var delivery=new{role="Rear service doorway",width=Hit(new Vector3(1.6f,1.3f,-3.2f),Vector3.left)+Hit(new Vector3(1.6f,1.3f,-3.2f),Vector3.right),height=Hit(new Vector3(1.6f,.32f,-3.2f),Vector3.up)+.2f};var entries=new[]{main,delivery};
